<?php
require_once '../includes/auth.php';requireActiveUser();requireTenantContext();requireModulePermission('hotspot','view');global $conn;$tenantId=(int)getCurrentTenantId();$rows=[];$q=$conn->prepare("SELECT s.*,c.code,p.name package_name FROM hotspot_access_codes c LEFT JOIN hotspot_packages p ON p.id=c.package_id AND p.tenant_id=c.tenant_id LEFT JOIN hotspot_access_codes s ON s.id=c.id WHERE c.tenant_id=? ORDER BY c.id DESC LIMIT 200");if($q){$q->bind_param('i',$tenantId);$q->execute();$z=$q->get_result();while($r=$z->fetch_assoc())$rows[]=$r;$q->close();}$pageTitle='Hotspot Sales';require_once '../includes/header.php';?><div class="dashboard-card"><h2>Hotspot Sales</h2><p>Access-code sales and revenue workspace.</p><?php if(!$rows):?><p>No hotspot sales recorded yet.</p><?php else:?><div class="table-responsive"><table><thead><tr><th>Code</th><th>Plan</th><th>Status</th><th>Expiry</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['code'])?></td><td><?=e($r['package_name']??'—')?></td><td><?=e($r['status'])?></td><td><?=e($r['expires_at']??'—')?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div><?php require_once '../includes/footer.php';?>